using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options that use the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// --- 1. GetTypeInfo<T>(): strongly-typed metadata ---
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---
// With the default (reflection) resolver every type resolves,
// so Person will succeed:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGet Person  -> resolved ({info!.Type.Name})");
else
    Console.WriteLine("TryGet Person  -> not available");

// With a *source-gen* context that only knows about Person,
// an unknown type will return false instead of throwing:
var sgOptions = new JsonSerializerOptions
{
    TypeInfoResolver = SmallContext.Default
};

if (sgOptions.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGet Person  (source-gen) -> resolved");
else
    Console.WriteLine("TryGet Person  (source-gen) -> not available");

if (sgOptions.TryGetTypeInfo<UnknownType>(out _))
    Console.WriteLine("TryGet Unknown (source-gen) -> resolved");
else
    Console.WriteLine("TryGet Unknown (source-gen) -> not available");

// --- types used by the demo ---
public record Person(string Name, int Age);
public class UnknownType { }

// Source-gen context that only registers Person
[JsonSerializable(typeof(Person))]
public partial class SmallContext : JsonSerializerContext { }

