    Console.WriteLine("TryGet Person  (source-gen) -> resolved");
else
    Console.WriteLine("TryGet Person  (source-gen) -> not available");

if (sgOptions.TryGetTypeInfo<UnknownType>(out _))
    Console.WriteLine("TryGet Unknown (source-gen) -> resolved");
